mapper.select:


    inner join sys_user u on u.user_name = tmovelibrarydetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tmovelibrarydetail.del_flag = '0'
     and tmovelibrarydetail.move_library_code like concat('%', #{moveLibraryCode}, '%')
     and tmovelibrarydetail.factory = #{factory}
     and tmovelibrarydetail.stock_id = #{stockId}
     and tmovelibrarydetail.material_id = #{materialId}
     and tmovelibrarydetail.count = #{count}
     and tmovelibrarydetail.batch_code like concat('%', #{batchCode}, '%')


${params.dataScope}
